import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static int n, k;
    static int[] head, to, next;
    static int edgeCount;
    static int[] order, parent;
    static int[] maxU, minC;

    static void addEdge(int u, int v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    static boolean check(int R) {
        Arrays.fill(maxU, 0);
        Arrays.fill(minC, 1000000000);

        int radars = 0;

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];

            if (minC[u] + maxU[u] <= R) {
                maxU[u] = -1;
            }

            if (maxU[u] == R) {
                radars++;
                minC[u] = 0;
                maxU[u] = -1;
            }

            int p = parent[u];
            if (p != 0) {
                if (maxU[u] >= 0) {
                    if (maxU[u] + 1 > maxU[p]) {
                        maxU[p] = maxU[u] + 1;
                    }
                }
                if (minC[u] != 1000000000) {
                    if (minC[u] + 1 < minC[p]) {
                        minC[p] = minC[u] + 1;
                    }
                }
            }
        }

        int root = order[0];
        if (maxU[root] >= 0) {
            radars++;
        }

        return radars <= k;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        k = fs.nextInt();

        head = new int[n + 1];
        Arrays.fill(head, -1);
        to = new int[2 * (n - 1)];
        next = new int[2 * (n - 1)];
        edgeCount = 0;

        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            addEdge(u, v);
            addEdge(v, u);
        }

        order = new int[n];
        parent = new int[n + 1];
        int headQueue = 0, tailQueue = 0;

        order[tailQueue++] = 1;
        parent[1] = 0;

        while (headQueue < tailQueue) {
            int u = order[headQueue++];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v != parent[u]) {
                    parent[v] = u;
                    order[tailQueue++] = v;
                }
            }
        }

        maxU = new int[n + 1];
        minC = new int[n + 1];

        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + c - '0';
                }
                c = read();
            }
            return res;
        }
    }
}
